// Aggregate budget for the real TCP peer so header rotation cannot yield unlimited guesses.
const PEER_MAX_ATTEMPTS = 30;
function peerKey(req) {
    return 'peer:' + (normalizePeerAddress(req.socket?.remoteAddress || '') || 'unknown');
}

router.post('/login', (req, res) => {
    const clientIp = getClientIp(req);
    const peer = peerKey(req);
    for (const key of [clientIp, peer]) {
        const rateCheck = checkLoginRateLimit(key);
        if (!rateCheck.allowed) {
            res.set('Retry-After', String(rateCheck.retryAfterSeconds));
            return res.status(429).json({ error: 'Too many failed login attempts.', retryAfter: rateCheck.retryAfterSeconds });
        }
    }
    // ... on failure: recordFailedLogin(clientIp); recordFailedLogin(peer, PEER_MAX_ATTEMPTS);
    // ... on success: recordSuccessfulLogin(clientIp) only (do not clear the peer budget).
});

